def is_arithmetic_progression(seq):
    if len(seq) < 2:
        return True
    diff = seq[1] - seq[0]
    return all(seq[i] - seq[i-1] == diff for i in range(2, len(seq)))

def split_into_arithmetic_progressions(n, a):
    a.sort()
    for i in range(1, n):
        for j in range(i+1, n):
            diff1 = a[i] - a[0]
            diff2 = a[j] - a[0]
            if diff1 % (i - 0) != 0 or diff2 % (j - 0) != 0:
                continue
            d1 = diff1 // (i - 0)
            d2 = diff2 // (j - 0)
            prog1 = [a[0] + k * d1 for k in range(i)]
            prog2 = [a[0] + k * d2 for k in range(j)]
            remaining = set(a) - set(prog1) - set(prog2)
            if not remaining:
                return [prog1, prog2]
    return "No solution"

